/* src/pages/HotelDetails.jsx */
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate, useOutletContext } from "react-router-dom";
import {
 MapPin,
 User,
 Settings,
 BedDouble,
 Building,
 ArrowLeft,
 Home,
 Loader2,
 CheckCircle,
 AlertCircle,
 Clock,
 DollarSign,
 Hash,
 ArrowRight
} from "lucide-react";
import Breadcrumbs from "../components/Breadcrumbs";

/**
 * HotelDetails page
 */
export default function HotelDetails() {
 const { user } = useOutletContext() || {};
 const { id } = useParams();
 const navigate = useNavigate();
 const [hotel, setHotel] = useState(null);
 const [rooms, setRooms] = useState([]);
 const [loading, setLoading] = useState(true);
 const [roomsLoading, setRoomsLoading] = useState(true);

 // load hotel details
 const fetchHotel = async () => {
 try {
 const res = await axios.get(`/api/hotels/${id}`);
 setHotel(res.data || null);
 } catch (err) {
 console.error("Failed to load hotel:", err);
 setHotel(null);
 }
 };

 const fetchRooms = async () => {
 setRoomsLoading(true);
 try {
 const res = await axios.get(`/api/hotels/${id}/rooms`);
 setRooms(res.data.rooms || []);
 } catch (err) {
 console.error("Failed to load rooms:", err);
 setRooms([]);
 } finally {
 setRoomsLoading(false);
 }
 };

 useEffect(() => {
 let mounted = true;
 const loadData = async () => {
 setLoading(true);
 try {
 await Promise.all([fetchHotel(), fetchRooms()]);
 } catch (err) {
 console.error("Error loading hotel data:", err);
 } finally {
 if (mounted) setLoading(false);
 }
 };
 loadData();
 return () => { mounted = false; };
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [id]);

 // compute canManage using the same logic as RoomsManager
 const computeCanManage = (userObj, hotelObj) => {
 if (!userObj) return false;
 if (userObj.role === "admin") return true;
 if (!hotelObj) return false;
 if (String(userObj.id) === String(hotelObj.manager_id)) return true;
 if (userObj.role === "staff") {
 const userHotelId = userObj.hotel_id || userObj.hotelId || userObj.hotel || null;
 if (userHotelId && String(userHotelId) === String(hotelObj.id)) return true;
 if (userObj.branch && hotelObj.branch && String(userObj.branch) === String(hotelObj.branch)) return true;
 }
 return false;
 };

 const canManage = computeCanManage(user, hotel);

 const goToManage = () => {
 if (!hotel || !hotel.id) return;
 navigate(`/hotels/${hotel.id}/rooms`);
 };

 // Helper for Status Badge
 const getStatusBadge = (status) => {
 const s = (status || "").toLowerCase();
 if (s === "available") {
 return (
 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-green-100 text-green-700 border border-green-200">
 <CheckCircle className="w-3.5 h-3.5" /> Available
 </span>
 );
 }
 if (s === "occupied") {
 return (
 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-orange-100 text-orange-700 border border-orange-200">
 <Clock className="w-3.5 h-3.5" /> Occupied
 </span>
 );
 }
 if (s === "maintenance") {
 return (
 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-red-100 text-red-700 border border-red-200">
 <AlertCircle className="w-3.5 h-3.5" /> Maintenance
 </span>
 );
 }
 return (
 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-gray-100 text-gray-600 border border-gray-200">
 <Hash className="w-3.5 h-3.5" /> {status || "Pending"}
 </span>
 );
 };

 if (loading) {
 return (
 <div className="min-h-screen bg-gray-50 flex items-center justify-center">
 <div className="p-3 sm:p-4 md:p-6 w-[90%] max-w-[1800px] mx-auto">
 <Loader2 className="w-10 h-10 text-purple-600 animate-spin" />
 <div className="text-gray-500 font-medium">Loading details...</div>
 </div>
 </div>
 );
 }

 if (!hotel) {
 return (
 <div className="min-h-screen bg-gray-50 p-6 flex justify-center">
 <div className="w-full max-w-4xl">
 <div className="bg-red-50 border border-red-200 rounded-xl p-6 flex items-center gap-4 text-red-700">
 <AlertCircle className="w-8 h-8" />
 <div>
 <h2 className="text-lg font-bold">Hotel not found</h2>
 <p className="text-sm text-red-600">The hotel you are looking for does not exist or has been removed.</p>
 </div>
 <button
 onClick={() => navigate('/hotels')}
 className="btn-secondary rounded-xl"
 >
 Go Back
 </button>
 </div>
 </div>
 </div>
 );
 }

 return (
 <div className="min-h-screen bg-gray-50 font-sans pb-12" style={{ fontFamily: "'Inter', system-ui, sans-serif" }}>
 <div className="p-3 sm:p-4 md:p-6 w-[95%] w-[90%] max-w-[1800px] mx-auto">
 {/* HEADER SECTION - Unified Card */}
 <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 sm:p-8 mb-6">
 <div className="flex flex-col gap-6">
 {/* Top Row: Back & Breadcrumbs */}
 <div className="flex items-center gap-3">
 <button
 onClick={() => navigate('/hotels')}
 className="group flex items-center gap-2 text-sm font-semibold text-slate-600 bg-white border border-slate-200 px-5 py-2.5 rounded-xl shadow-sm hover:border-teal-500 hover:text-teal-600 "
 >
 <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
 <span>Back</span>
 </button>
 <Breadcrumbs
 items={[
 { label: 'Hotels', path: '/admin/hotels' },
 { label: hotel.name }
 ]}
 />
 </div>

 {/* Hero Section Content (Title, Badges, Actions) */}
 <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 pt-2">
 <div>
 <div className="inline-flex items-center gap-1.5 bg-purple-50 text-purple-700 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider mb-3">
 <Building className="w-3 h-3" /> Property Details
 </div>
 <h1 className="text-3xl sm:text-4xl font-black text-gray-900 mb-4 tracking-tight leading-tight">{hotel.name}</h1>

 <div className="flex flex-wrap items-center gap-3">
 {hotel.city && (
 <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 rounded-xl border border-blue-100 text-blue-700">
 <MapPin className="w-4 h-4" />
 <span className="text-sm font-semibold">{hotel.city}</span>
 </div>
 )}
 {hotel.manager_name && (
 <div className="flex items-center gap-2 px-3 py-1.5 bg-green-50 rounded-xl border border-green-100 text-green-700">
 <User className="w-4 h-4" />
 <span className="text-sm font-semibold">Manager: {hotel.manager_name}</span>
 </div>
 )}
 </div>
 </div>

 {/* Actions */}
 <div className="flex items-center gap-3 mt-2 md:mt-0">
 {canManage && (
 <button
 onClick={goToManage}
 className="rounded-xl btn-primary"
 >
 <Settings className="w-4 h-4" />
 Manage Rooms
 </button>
 )}
 </div>
 </div>
 </div>
 </div>

 {/* Rooms Section */}
 <div className="flex flex-col gap-6">
 <div className="flex items-center justify-between">
 <div className="flex items-center gap-3">
 <div className="p-2 bg-purple-100 text-purple-600 rounded-xl">
 <BedDouble className="w-6 h-6" />
 </div>
 <h3 className="text-2xl font-bold text-gray-900">Available Rooms</h3>
 </div>
 <span className="bg-white text-gray-600 px-4 py-1.5 rounded-full text-sm font-bold border border-gray-200 shadow-sm">
 {rooms.length} Total
 </span>
 </div>

 {roomsLoading ? (
 <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-12 text-center">
 <Loader2 className="w-12 h-12 text-purple-500 animate-spin mx-auto mb-4" />
 <p className="text-gray-500 font-medium">Fetching room data...</p>
 </div>
 ) : rooms.length === 0 ? (
 <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-16 text-center">
 <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
 <BedDouble className="w-8 h-8 text-gray-400" />
 </div>
 <h3 className="text-lg font-bold text-gray-900 mb-1">No Rooms Found</h3>
 <p className="text-gray-500">There are currently no rooms listed for this property.</p>
 </div>
 ) : (
 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
 {rooms.map((r) => (
 <div
 key={r.id}
 className="group bg-white rounded-xl p-5 shadow-sm border border-gray-200 hover:border-purple-200 flex flex-col justify-between"
 >
 {/* Card Header */}
 <div className="flex justify-between items-start mb-4">
 <div>
 <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1">Room No.</div>
 <div className="text-2xl font-black text-gray-800 group-hover:text-purple-600 transition-colors">
 {r.room_number}
 </div>
 </div>
 {getStatusBadge(r.status)}
 </div>

 {/* Room Type Tag */}
 <div className="mb-6">
 <span className="inline-flex items-center px-2.5 py-1 rounded-xl text-xs font-medium bg-gray-100 text-gray-600">
 {r.type || 'Standard Room'}
 </span>
 </div>

 {/* Card Footer / Price */}
 <div className="pt-4 border-t border-gray-100 flex items-center justify-between">
 <div>
 <div className="flex items-baseline gap-0.5">
 <span className="text-lg font-bold text-gray-900">₹{Number(r.rate || 0).toLocaleString()}</span>
 <span className="text-xs text-gray-500 font-medium">/ night</span>
 </div>
 </div>
 {canManage && (
 <button
 onClick={goToManage}
 className="p-2 text-gray-400 hover:text-purple-600 hover:bg-purple-50 rounded-xl transition-colors"
 title="Edit Room"
 >
 <Settings className="w-4 h-4" />
 </button>
 )}
 </div>
 </div>
 ))}
 </div>
 )}
 </div>
 </div>
 </div>
 );
}